 * Lists customers in a lazily loaded {@link Grid}, with a filter bar that
 * narrows the list by name and status.
 *
 * <p>The grid never holds the whole data set: it asks the backend for one page
 * at a time and asks separately for the total row count, and both the name and
 * the status filter are applied by the backend.
 */
@Route("")
@PageTitle("Customers")
public class CustomerListView extends VerticalLayout implements BeforeEnterObserver {

    private final CustomerService customerService;
    private final Grid<Customer> grid = new Grid<>(Customer.class, false);
