    private GridLazyDataView<Customer> dataView;
    private CustomerFilter filter = CustomerFilter.NONE;
    private final int total;
    private boolean suppressFilterEvents;

    public CustomerListView(CustomerService customerService) {
        this.customerService = customerService;
        this.total = customerService.count(CustomerFilter.NONE);

        setSizeFull();
        add(new H2("Customers"), buildFilterBar(), summary, grid);

        configureGrid();
        updateSummary(total);
    }

    private HorizontalLayout buildFilterBar() {
        nameFilter.setPlaceholder("Filter by name");
        nameFilter.setValueChangeMode(ValueChangeMode.LAZY);
        nameFilter.setValueChangeTimeout(300);
        nameFilter.addValueChangeListener(event -> onFilterChanged());

