+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A name/status filter understood by {@link CustomerRepository}.
+ *
+ * @param name      free text; split on whitespace into terms, every one of which
+ *                  must appear, case- and accent-insensitively, in the customer's
+ *                  first name or last name. Blank matches every customer.
+ * @param statuses  statuses to keep; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = name == null ? "" : name.strip();
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Whether {@code customer} satisfies both the name and the status filter. */
+    public boolean matches(Customer customer) {
+        return matchesName(customer) && matchesStatus(customer);
+    }
+
+    private boolean matchesName(Customer customer) {
+        List<String> terms = nameTerms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private List<String> nameTerms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return WHITESPACE.splitAsStream(name).map(CustomerFilter::fold).toList();
+    }
+
+    /** Lower-cases and strips diacritics, so matching ignores case and accents. */
+    private static String fold(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
