+    @BeforeEach
+    void clearLog() {
+        queryLog.clear();
+    }
+
+    @Test
+    void typingNarrowsTheGridAndUpdatesTheAddressBarWithoutOneQueryPerKeystroke() {
+        TextFieldElement nameFilter = new TextFieldElement(
+                getPage().locator("vaadin-text-field[placeholder='Filter by name']"));
+        GridElement grid = GridElement.get(getPage());
+
+        Locator input = nameFilter.getInputLocator();
+        input.pressSequentially("Aaltonen", new Locator.PressSequentiallyOptions().setDelay(50));
+
+        getPage().waitForTimeout(600);
+        grid.waitForGridToStopLoading();
+
+        assertEquals(15, grid.getTotalRowCount(), "typing 'Aaltonen' should narrow the grid to the matching rows");
+        assertTrue(getPage().url().contains("name=Aaltonen"),
+                "the address bar should carry the filter: " + getPage().url());
+
+        int queriesForOneWordTyped = queryLog.pageQueries().size() + queryLog.countQueries().size();
+        assertTrue(queriesForOneWordTyped <= 2,
+                "typing a name should cost at most a couple of backend queries, not one per keystroke; got "
+                        + queriesForOneWordTyped);
+    }
+
+    @Test
+    void statusSelectionUpdatesTheAddressBarWithoutANewHistoryEntry() {
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(getPage(), "Status");
+        GridElement grid = GridElement.get(getPage());
+
+        long historyLengthBefore = ((Number) getPage().evaluate("() => window.history.length")).longValue();
+
+        statusFilter.selectItem("ACTIVE");
+        grid.waitForGridToStopLoading();
+        statusFilter.selectItem("CLOSED");
+        grid.waitForGridToStopLoading();
+
+        assertEquals(333, grid.getTotalRowCount());
+        assertTrue(getPage().url().contains("status=ACTIVE,CLOSED")
+                        || getPage().url().contains("status=ACTIVE%2CCLOSED"),
+                "the address bar should carry the status filter: " + getPage().url());
+
+        long historyLengthAfter = ((Number) getPage().evaluate("() => window.history.length")).longValue();
+        assertEquals(historyLengthBefore, historyLengthAfter,
+                "changing the filter twice must not push any new history entry");
+    }
+
+    @Test
+    void openingAUrlWithParametersAppliesTheFilterAndShowsItInTheFields() {
+        getPage().navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        getPage().waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        TextFieldElement nameFilter = new TextFieldElement(
+                getPage().locator("vaadin-text-field[placeholder='Filter by name']"));
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(getPage(), "Status");
+        GridElement grid = GridElement.get(getPage());
+        grid.waitForGridToStopLoading();
+
+        assertEquals("vir", nameFilter.getValue());
+        assertEquals(java.util.List.of("ACTIVE", "CLOSED"), statusFilter.getSelectedItems());
+        assertEquals(10, grid.getTotalRowCount());
+    }
+}
